// Placeholder runtime config. In the Docker image this file is regenerated by
// docker-entrypoint.sh at container startup from environment variables, so the
// same built image can be deployed to any environment (dev/staging/prod/k8s)
// without rebuilding. For local `npm start` development this default is unused
// because AuthContext falls back to process.env.REACT_APP_BACKEND_URL.
window._env_ = {
  REACT_APP_BACKEND_URL: ""
};
